function createLibraryCore(){
  const folderKey=kind=>kind==='characters'?'characterFolders':kind==='scenes'?'sceneFolders':'assetFolders';
  const items=(p,kind)=>kind==='characters'?p.characters:kind==='scenes'?p.scenes:p.assets;
  function normalize(p){p.assetFolders??=[];p.characterFolders??=[];p.sceneFolders??=[];return p}
  function folders(p,kind){normalize(p);return p[folderKey(kind)]}
  function descendants(p,kind,id){const result=new Set([id]);let changed=true;while(changed){changed=false;for(const f of folders(p,kind))if(result.has(f.parentId||'')&&!result.has(f.id)){result.add(f.id);changed=true}}return result}
  function folderPath(p,kind,id){const parts=[],seen=new Set();while(id&&!seen.has(id)){seen.add(id);const f=folders(p,kind).find(f=>f.id===id);if(!f)break;parts.unshift(f.name);id=f.parentId}return parts.join('/')}
  function createFolder(p,kind,name,parentId=''){name=String(name).trim();if(!name||name.length>80)throw Error('分类名称须为 1–80 个字符');const all=folders(p,kind);if(parentId&&!all.some(f=>f.id===parentId))throw Error('上级分类不存在');if(all.some(f=>f.name===name&&(f.parentId||'')===parentId))throw Error('同一位置已有同名分类');const f={id:crypto.randomUUID(),name,parentId};all.push(f);return f}
  function ensurePath(p,kind,relative,parentId=''){for(const name of String(relative).replace(/\\/g,'/').split('/').filter(Boolean)){if(name==='.'||name==='..')throw Error('导入分类路径无效');let f=folders(p,kind).find(f=>f.name===name&&(f.parentId||'')===parentId);if(!f)f=createFolder(p,kind,name,parentId);parentId=f.id}return parentId}
  function moveItems(p,kind,ids,folderId=''){if(folderId&&!folders(p,kind).some(f=>f.id===folderId))throw Error('目标分类不存在');const selected=new Set(ids);for(const item of items(p,kind))if(selected.has(item.id))item.folderId=folderId}
  function removeFolder(p,kind,id){const all=folders(p,kind),f=all.find(f=>f.id===id);if(!f)return;for(const child of all)if(child.parentId===id)child.parentId=f.parentId||'';for(const item of items(p,kind))if(item.folderId===id)item.folderId=f.parentId||'';p[folderKey(kind)]=all.filter(f=>f.id!==id)}
  function removeAssets(p,ids){const removed=new Set(ids);p.assets=p.assets.filter(a=>!removed.has(a.id));if(removed.has(p.menu?.background))p.menu.background='';for(const c of p.characters){if(removed.has(c.asset))c.asset='';for(const v of c.variants||[])if(removed.has(v.asset))v.asset=''}if(removed.has(p.dialogueStyle?.image))p.dialogueStyle.image='';for(const s of p.scenes)for(const b of s.blocks){if(removed.has(b.asset))b.asset='';if(removed.has(b.voice?.asset))delete b.voice;if(removed.has(b.dialogueStyle?.image))b.dialogueStyle.image=''}}
  function characterReferences(p,id){let dialogue=0,portrait=0;for(const s of p.scenes)for(const b of s.blocks)if(b.speaker===id){if(b.type==='dialogue')dialogue++;if(b.type==='portrait')portrait++}return {dialogue,portrait}}
  function removeCharacter(p,id,replacement=''){if(replacement===id||replacement&&!p.characters.some(c=>c.id===replacement))throw Error('替代角色无效');const refs=characterReferences(p,id);p.characters=p.characters.filter(c=>c.id!==id);for(const s of p.scenes){s.blocks=s.blocks.filter(b=>!(b.type==='portrait'&&b.speaker===id&&!replacement));for(const b of s.blocks)if(b.speaker===id){if(replacement){b.speaker=replacement;b.variant='';delete b.portraitLayout}else if(b.type==='dialogue'){b.type='narration';delete b.speaker;delete b.variant;delete b.position;delete b.portraitLayout}}}for(const name of Object.keys(p.textRoleAliases||{}))if(p.textRoleAliases[name]===id){if(replacement)p.textRoleAliases[name]=replacement;else delete p.textRoleAliases[name]}return refs}
  function validate(p){for(const kind of ['assets','characters','scenes']){const all=folders(p,kind);if(!Array.isArray(all))throw Error('分类数据格式无效');const ids=new Set();for(const f of all){if(typeof f.id!=='string'||!f.id||ids.has(f.id)||typeof f.name!=='string'||!f.name.trim())throw Error('分类名称或标识无效');ids.add(f.id)}for(const f of all){if(f.parentId&&!ids.has(f.parentId))throw Error('上级分类不存在');const seen=new Set([f.id]);let parent=f.parentId;while(parent){if(seen.has(parent))throw Error('分类不能互相嵌套形成循环');seen.add(parent);parent=all.find(f=>f.id===parent)?.parentId}}for(const item of items(p,kind))if(item.folderId&&!ids.has(item.folderId))throw Error('素材、角色或章节的分类不存在')}return p}
  return {normalize,folders,folderPath,descendants,createFolder,ensurePath,moveItems,removeFolder,removeAssets,characterReferences,removeCharacter,validate};
}
globalThis.KotobaLibrary=createLibraryCore();
if(typeof module!=='undefined')module.exports=KotobaLibrary;
